-- Import the Pokémon Event Locator stores verified as unique to the Wizards Lead migrations for Arcane Fortress.
-- The audited 2026-08-10 workbook snapshot is embedded so deployments do not depend on local files.
-- Source total: 1375 stores with postal codes; 1287 with an extracted state/region.
-- Pokémon result cards did not expose phone numbers, so all same-country + normalized-ZIP Wizards candidates were excluded conservatively.

DO $migration_guard$
DECLARE
    organization_count INTEGER;
    target_organization_id TEXT;
BEGIN
    SELECT COUNT(*), MIN("id")
    INTO organization_count, target_organization_id
    FROM "Organization"
    WHERE "name" = 'Arcane Fortress';

    IF organization_count > 1 THEN
        RAISE EXCEPTION 'Pokémon unique-store Lead import expected at most one organization named Arcane Fortress, found %', organization_count;
    END IF;

    IF organization_count = 1 AND NOT EXISTS (
        SELECT 1
        FROM "OrganizationMembership" membership
        INNER JOIN "users" app_user ON app_user."id" = membership."userId"
        WHERE membership."organizationId" = target_organization_id
          AND membership."status" = 'ACTIVE'
          AND app_user."status" = 'ACTIVE'
    ) THEN
        RAISE EXCEPTION 'Pokémon unique-store Lead import found Arcane Fortress but no active organization member with an active user';
    END IF;
END;
$migration_guard$;

WITH target_organization AS (
    SELECT "id"
    FROM "Organization"
    WHERE "name" = 'Arcane Fortress'
), target_owner AS (
    SELECT
        target_organization."id" AS "organizationId",
        selected_owner."userId"
    FROM target_organization
    INNER JOIN LATERAL (
        SELECT membership."userId"
        FROM "OrganizationMembership" membership
        INNER JOIN "users" app_user ON app_user."id" = membership."userId"
        WHERE membership."organizationId" = target_organization."id"
          AND membership."status" = 'ACTIVE'
          AND app_user."status" = 'ACTIVE'
        ORDER BY
            CASE WHEN membership."role" = 'ADMIN' THEN 0 ELSE 1 END,
            membership."createdAt",
            membership."id"
        LIMIT 1
    ) selected_owner ON TRUE
), source_store AS (
    SELECT *
    FROM jsonb_to_recordset($pokemon_store_data$
