$pokemon_store_data$::jsonb) AS store_data(
        "sourceKey" TEXT,
        "sourceMarket" TEXT,
        "storeName" TEXT,
        "address" TEXT,
        "country" TEXT,
        "state" TEXT,
        "postalCode" TEXT,
        "sourceSearch" TEXT,
        "resolvedSearch" TEXT,
        "searchPageUrl" TEXT,
        "extractedAt" TEXT
    )
), source_stats AS (
    SELECT
        COUNT(*) AS row_count,
        COUNT(DISTINCT "sourceKey") AS distinct_key_count,
        COUNT(*) FILTER (WHERE NULLIF(BTRIM("postalCode"), '') IS NOT NULL) AS postal_code_count
    FROM source_store
), source_assertion AS (
    SELECT 1 / CASE
        WHEN row_count = 1375
         AND distinct_key_count = 1375
         AND postal_code_count = 1375
        THEN 1
        ELSE 0
    END AS ok
    FROM source_stats
), normalized_source_store AS (
    SELECT
        source_store.*,
        UPPER(BTRIM("country")) AS "countryKey",
        CASE
            WHEN UPPER(BTRIM("country")) = 'UNITED STATES'
            THEN LEFT(UPPER(REGEXP_REPLACE(COALESCE("postalCode", ''), '[^A-Z0-9]', '', 'g')), 5)
            ELSE UPPER(REGEXP_REPLACE(COALESCE("postalCode", ''), '[^A-Z0-9]', '', 'g'))
        END AS "postalCodeKey"
    FROM source_store
), wizard_lead_location AS (
    SELECT
        wizard_lead."id",
        UPPER(BTRIM(COALESCE(wizard_lead."country", ''))) AS "countryKey",
        CASE
            WHEN UPPER(BTRIM(COALESCE(wizard_lead."country", ''))) = 'UNITED STATES'
            THEN LEFT(UPPER(REGEXP_REPLACE(COALESCE(wizard_lead."postalCode", ''), '[^A-Z0-9]', '', 'g')), 5)
            ELSE UPPER(REGEXP_REPLACE(COALESCE(wizard_lead."postalCode", ''), '[^A-Z0-9]', '', 'g'))
        END AS "postalCodeKey"
    FROM "Lead" wizard_lead
    CROSS JOIN target_organization
    WHERE wizard_lead."organizationId" = target_organization."id"
      AND wizard_lead."id" LIKE 'lead-wizards-store-%'
)
INSERT INTO "Lead" (
    "id",
    "organizationId",
    "status",
    "lastName",
    "company",
    "description",
    "ownerId",
    "country",
    "street",
    "postalCode",
    "state",
    "leadSource",
    "createdById",
    "updatedById",
    "createdAt",
    "updatedAt"
)
SELECT
    'lead-pokemon-store-' || source_store."sourceKey" || '-' || SUBSTRING(MD5(target_owner."organizationId"), 1, 12),
    target_owner."organizationId",
    'New',
    source_store."storeName",
    source_store."storeName",
    CONCAT_WS(
        E'\n',
        'Imported from Pokémon Event Locator verified snapshot 2026-08-10.',
        'Source market: ' || source_store."sourceMarket",
        'Uniqueness audit: no Wizards Lead in the same normalized country + postal code.',
        'Phone: not provided by the Pokémon public result card.',
        'First discovery search: ' || source_store."sourceSearch",
        'Resolved search: ' || source_store."resolvedSearch",
        'Search page URL: ' || source_store."searchPageUrl",
        'Extracted at: ' || source_store."extractedAt"
    ),
    target_owner."userId",
    source_store."country",
    source_store."address",
    source_store."postalCode",
    source_store."state",
    'Web',
    target_owner."userId",
    target_owner."userId",
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM normalized_source_store source_store
CROSS JOIN target_owner
CROSS JOIN source_assertion
WHERE source_assertion.ok = 1
  AND NOT EXISTS (
      SELECT 1
      FROM wizard_lead_location wizard_lead
      WHERE wizard_lead."countryKey" = source_store."countryKey"
        AND wizard_lead."postalCodeKey" = source_store."postalCodeKey"
  )
ON CONFLICT ("id") DO NOTHING;
